/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.event
 */
function evaluateEvent({
    api,
    event
}) {
    var datasourceType = event.payload.params.dataSourceType;
	var indicatorId = event.payload.params.indicatorSysid;
    if (datasourceType === 'indicator') {
        if (indicatorId === "9f48d534771131101b803a91fa5a9901") {
            return {
                route: null,
                fields: null,
                params: null,
                redirect: null,
                passiveNavigation: null,
                title: null,
                multiInstField: null,
                targetRoute: null,
                external: {
                    url: "now/security-center/critical_updates_home",
                    target: "_blank"

                },
                navigationOptions: null
            };
        } else {
            return {
                route: 'ac_kpi_details',
                fields: {
                    'uuid': indicatorId
                },
                params: null,
                redirect: null,
                passiveNavigation: null,
                title: null,
                multiInstField: null,
                targetRoute: null,
                external: null,
                navigationOptions: null
            };
        }
    } else if (datasourceType === 'table') {
        return {
            route: 'simplelist',
            fields: {
                'table': event.payload.params.table
            },
            params: {
                'listTitle': event.payload.params.listTitle,
                'query': event.payload.params.query,
            },
            redirect: null,
            passiveNavigation: null,
            title: null,
            multiInstField: null,
            targetRoute: null,
            external: null,
            navigationOptions: null
        };
    }
}

